begin;
-- Additive expansion. Existing rows/IDs remain valid; no legacy record is deleted.
alter table public.profiles add column onboarding_completed_at timestamptz;
create table public.user_learning_goals(user_id uuid not null references auth.users(id) on delete cascade,goal text not null check(goal in ('jlpt','student','future_worker','professional','tourist','teacher','organization_admin')),created_at timestamptz not null default now(),primary key(user_id,goal));
insert into public.user_learning_goals(user_id,goal) select id,case learning_goal when 'study' then 'student' when 'work' then 'future_worker' when 'business' then 'professional' when 'travel' then 'tourist' else 'jlpt' end from public.profiles;
alter table public.user_learning_goals enable row level security;
revoke all on public.user_learning_goals from anon,authenticated;
grant select on public.user_learning_goals to authenticated;
create policy goals_owner on public.user_learning_goals for select to authenticated using(user_id=(select auth.uid()));
create function public.set_learning_goals(p_goals text[]) returns void language plpgsql security definer set search_path='' as $$declare uid uuid:=auth.uid();begin
 if uid is null then raise exception 'Authentication required';end if;
 if p_goals is null or cardinality(p_goals) not between 1 and 7 or exists(select 1 from unnest(p_goals) g where g is null or g not in ('jlpt','student','future_worker','professional','tourist','teacher','organization_admin')) or (select count(distinct g) from unnest(p_goals) g)<>cardinality(p_goals) then raise exception 'Invalid goals';end if;
 if not exists(select 1 from public.profiles where id=uid) then raise exception 'Profile unavailable';end if;
 delete from public.user_learning_goals where user_id=uid;
 insert into public.user_learning_goals(user_id,goal) select uid,g from unnest(p_goals) g;
 update public.profiles set onboarding_completed_at=coalesce(onboarding_completed_at,now()),updated_at=now() where id=uid;
end$$;
revoke all on function public.set_learning_goals(text[]) from public;grant execute on function public.set_learning_goals(text[]) to authenticated;

create table public.learning_programs(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),title text not null check(char_length(title) between 1 and 180),summary text not null default '' check(char_length(summary)<=2000),category text not null check(category in ('learn','jlpt','jft-basic','ssw','business','life-in-japan','ai-practice','organizations')),review_status text not null default 'draft' check(review_status in ('draft','in_review','approved')),published boolean not null default false check(not published or review_status='approved'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.courses add column program_id uuid references public.learning_programs(id) on delete restrict;
alter table public.courses drop constraint if exists courses_slug_check;
alter table public.courses add constraint courses_slug_format check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
alter table public.courses add column review_status text not null default 'draft' check(review_status in ('draft','in_review','approved'));
update public.courses set review_status='approved' where published;
alter table public.courses add constraint courses_reviewed_before_publication check(not published or review_status='approved');
create table public.course_modules(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete restrict,title text not null check(char_length(title) between 1 and 180),position integer not null check(position>=0),review_status text not null default 'draft' check(review_status in ('draft','in_review','approved')),published boolean not null default false check(not published or review_status='approved'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(course_id,position),unique(course_id,id));
alter table public.lessons add column module_id uuid;
alter table public.lessons add foreign key(course_id,module_id) references public.course_modules(course_id,id) on delete restrict;
alter table public.lessons add column review_status text not null default 'draft' check(review_status in ('draft','in_review','approved'));
update public.lessons set review_status='approved' where published;
alter table public.lessons add constraint lessons_reviewed_before_publication check(not published or review_status='approved');
create table public.audio_assets(id uuid primary key default gen_random_uuid(),title text not null,url text check(url ~ '^https://'),mime_type text check(mime_type in ('audio/mpeg','audio/ogg','audio/wav','audio/mp4')),status text not null default 'planned' check(status in ('planned','processing','ready')),duration_seconds integer check(duration_seconds>0),published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(not published or (status='ready' and url is not null and mime_type is not null)));
create table public.lesson_blocks(id uuid primary key default gen_random_uuid(),lesson_id uuid not null references public.lessons(id) on delete restrict,kind text not null check(kind in ('text','example','flashcards','quiz','audio')),content jsonb not null default '{}' check(jsonb_typeof(content)='object'),schema_version integer not null default 1 check(schema_version=1),position integer not null check(position>=0),deck_id uuid references public.flashcard_decks(id) on delete restrict,question_bank_id uuid references public.question_banks(id) on delete restrict,audio_asset_id uuid references public.audio_assets(id) on delete restrict,review_status text not null default 'draft' check(review_status in ('draft','in_review','approved')),published boolean not null default false check(not published or review_status='approved'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(lesson_id,position),check(kind<>'flashcards' or deck_id is not null),check(kind<>'quiz' or question_bank_id is not null),check(kind<>'audio' or audio_asset_id is not null));
create table public.content_translations(id uuid primary key default gen_random_uuid(),program_id uuid references public.learning_programs(id) on delete restrict,course_id uuid references public.courses(id) on delete restrict,module_id uuid references public.course_modules(id) on delete restrict,lesson_id uuid references public.lessons(id) on delete restrict,block_id uuid references public.lesson_blocks(id) on delete restrict,locale text not null check(locale in ('en','ja','ne','hi')),title text not null check(char_length(title) between 1 and 180),content jsonb not null default '{}' check(jsonb_typeof(content)='object'),review_status text not null default 'draft' check(review_status in ('draft','in_review','approved')),published boolean not null default false check(not published or review_status='approved'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(program_id,course_id,module_id,lesson_id,block_id)=1),unique nulls not distinct(program_id,course_id,module_id,lesson_id,block_id,locale));
create table public.program_enrollments(user_id uuid not null references auth.users(id) on delete cascade,program_id uuid not null references public.learning_programs(id) on delete restrict,created_at timestamptz not null default now(),primary key(user_id,program_id));
create table public.lesson_block_progress(user_id uuid not null references auth.users(id) on delete cascade,block_id uuid not null references public.lesson_blocks(id) on delete cascade,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,block_id));
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 180),kind text not null check(kind in ('institute','employer')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.organization_members(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','administrator','instructor','learner')),created_at timestamptz not null default now(),primary key(organization_id,user_id));
-- Organization access uses assigned memberships, never editable profile goals.
create function public.is_organization_member(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_members where organization_id=p_org and user_id=(select auth.uid()))$$;
create function public.is_organization_staff(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_members where organization_id=p_org and user_id=(select auth.uid()) and role in ('owner','administrator','instructor'))$$;
revoke all on function public.is_organization_member(uuid),public.is_organization_staff(uuid) from public;
grant execute on function public.is_organization_member(uuid),public.is_organization_staff(uuid) to authenticated;
create table public.organization_programs(organization_id uuid not null references public.organizations(id) on delete cascade,program_id uuid not null references public.learning_programs(id) on delete restrict,created_at timestamptz not null default now(),primary key(organization_id,program_id));
create table public.training_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,program_id uuid references public.learning_programs(id) on delete restrict,title text not null,starts_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id));
create table public.attendance_records(organization_id uuid not null,session_id uuid not null,student_id uuid not null,status text not null check(status in ('present','absent','late','excused')),recorded_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(session_id,student_id),foreign key(organization_id,session_id) references public.training_sessions(organization_id,id) on delete cascade,foreign key(organization_id,student_id) references public.organization_members(organization_id,user_id) on delete cascade);
create table public.training_reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,author_id uuid not null references auth.users(id) on delete restrict,title text not null,summary jsonb not null default '{}' check(jsonb_typeof(summary)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ai_scenarios(id uuid primary key default gen_random_uuid(),program_id uuid references public.learning_programs(id) on delete restrict,title text not null,prompt_template text not null,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ai_roleplay_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,scenario_id uuid not null references public.ai_scenarios(id) on delete restrict,status text not null default 'planned' check(status in ('planned','active','completed','failed')),provider_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tutor_bookings(id uuid primary key default gen_random_uuid(),learner_id uuid not null references auth.users(id) on delete cascade,tutor_id uuid not null references auth.users(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'requested' check(status in ('requested','confirmed','cancelled','completed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at),check(learner_id<>tutor_id));
create table public.visa_checklist_templates(id uuid primary key default gen_random_uuid(),program_id uuid references public.learning_programs(id) on delete restrict,title text not null,informational_notice text not null,source_url text check(source_url ~ '^https://'),reviewed_at timestamptz,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(not published or (source_url is not null and reviewed_at is not null)));
create table public.visa_checklist_items(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.visa_checklist_templates(id) on delete cascade,title text not null,position integer not null check(position>=0),created_at timestamptz not null default now(),unique(template_id,position));
create table public.examinations(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.learning_programs(id) on delete restrict,bank_id uuid not null references public.question_banks(id) on delete restrict,title text not null,version integer not null default 1 check(version>0),requires_human_review boolean not null default false,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,bank_id));
alter table public.quiz_attempts add column examination_id uuid;
alter table public.quiz_attempts add foreign key(examination_id,bank_id) references public.examinations(id,bank_id) on delete restrict;
create table public.examination_reviews(id uuid primary key default gen_random_uuid(),attempt_id uuid not null unique references public.quiz_attempts(id) on delete cascade,reviewer_id uuid not null references private.admin_users(user_id) on delete restrict,status text not null default 'assigned' check(status in ('assigned','in_review','released')),feedback jsonb not null default '{}' check(jsonb_typeof(feedback)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table private.content_review_events(id bigint generated always as identity primary key,entity_kind text not null,entity_id uuid not null,actor_id uuid references auth.users(id) on delete set null,review_status text not null,published boolean not null,created_at timestamptz not null default now());

-- Every new table denies access unless explicitly granted below.
do $$declare t text;begin foreach t in array array['learning_programs','course_modules','audio_assets','lesson_blocks','content_translations','program_enrollments','lesson_block_progress','organizations','organization_members','organization_programs','training_sessions','attendance_records','training_reports','ai_scenarios','ai_roleplay_sessions','tutor_bookings','visa_checklist_templates','visa_checklist_items','examinations','examination_reviews'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
grant select on public.learning_programs,public.course_modules,public.lesson_blocks,public.content_translations,public.audio_assets,public.ai_scenarios,public.visa_checklist_templates,public.visa_checklist_items,public.examinations to anon,authenticated;
grant select on public.program_enrollments,public.lesson_block_progress,public.organizations,public.organization_members,public.organization_programs,public.training_sessions,public.attendance_records,public.training_reports,public.ai_roleplay_sessions,public.tutor_bookings,public.examination_reviews to authenticated;
grant insert,update,delete on public.learning_programs,public.course_modules,public.lesson_blocks,public.content_translations,public.audio_assets,public.organizations,public.organization_members,public.organization_programs,public.training_sessions,public.ai_scenarios,public.visa_checklist_templates,public.visa_checklist_items,public.examinations,public.examination_reviews to authenticated;
grant insert,update on public.program_enrollments,public.lesson_block_progress,public.attendance_records,public.training_reports to authenticated;
-- No client write grants for AI sessions or tutor bookings until real integrations exist.
create policy program_public on public.learning_programs for select using(published or (select public.is_admin()));
drop policy course_public on public.courses;
create policy course_public on public.courses for select using((published and (program_id is null or exists(select 1 from public.learning_programs p where p.id=program_id and p.published))) or (select public.is_admin()));
create policy module_public on public.course_modules for select using((published and exists(select 1 from public.courses c where c.id=course_id and c.published)) or (select public.is_admin()));
drop policy lesson_public on public.lessons;
create policy lesson_public on public.lessons for select using((published and exists(select 1 from public.courses c where c.id=course_id and c.published) and (module_id is null or exists(select 1 from public.course_modules m where m.id=module_id and m.published))) or (select public.is_admin()));
create policy block_public on public.lesson_blocks for select using((published and exists(select 1 from public.lessons l where l.id=lesson_id and l.published)) or (select public.is_admin()));
create policy translation_public on public.content_translations for select using((published and (exists(select 1 from public.learning_programs p where p.id=program_id and p.published) or exists(select 1 from public.courses c where c.id=course_id and c.published) or exists(select 1 from public.course_modules m where m.id=module_id and m.published) or exists(select 1 from public.lessons l where l.id=lesson_id and l.published) or exists(select 1 from public.lesson_blocks b where b.id=block_id and b.published))) or (select public.is_admin()));
create policy audio_public on public.audio_assets for select using((published and status='ready') or (select public.is_admin()));
create policy scenario_public on public.ai_scenarios for select using((published and (program_id is null or exists(select 1 from public.learning_programs p where p.id=program_id and p.published))) or (select public.is_admin()));
create policy checklist_public on public.visa_checklist_templates for select using((published and (program_id is null or exists(select 1 from public.learning_programs p where p.id=program_id and p.published))) or (select public.is_admin()));
create policy checklist_item_public on public.visa_checklist_items for select using(exists(select 1 from public.visa_checklist_templates t where t.id=template_id and t.published) or (select public.is_admin()));
create policy examination_public on public.examinations for select using((published and exists(select 1 from public.learning_programs p where p.id=program_id and p.published) and exists(select 1 from public.question_banks b where b.id=bank_id and b.published)) or (select public.is_admin()));
create policy enrollment_owner_read on public.program_enrollments for select to authenticated using(user_id=(select auth.uid()));
create policy enrollment_owner_insert on public.program_enrollments for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.learning_programs p where p.id=program_id and p.published));
create policy block_progress_owner on public.lesson_block_progress for select to authenticated using(user_id=(select auth.uid()));
create policy block_progress_insert on public.lesson_block_progress for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.lesson_blocks b where b.id=block_id and b.published));
create policy block_progress_update on public.lesson_block_progress for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.lesson_blocks b where b.id=block_id and b.published));
create policy org_read on public.organizations for select to authenticated using(public.is_organization_member(id) or (select public.is_admin()));
create policy org_members_read on public.organization_members for select to authenticated using(user_id=(select auth.uid()) or public.is_organization_staff(organization_id) or (select public.is_admin()));
create policy org_programs_read on public.organization_programs for select to authenticated using(public.is_organization_member(organization_id) or (select public.is_admin()));
create policy sessions_read on public.training_sessions for select to authenticated using(public.is_organization_member(organization_id) or (select public.is_admin()));
create policy attendance_read on public.attendance_records for select to authenticated using(student_id=(select auth.uid()) or public.is_organization_staff(organization_id) or (select public.is_admin()));
create policy attendance_insert on public.attendance_records for insert to authenticated with check(recorded_by=(select auth.uid()) and public.is_organization_staff(organization_id));
create policy attendance_update on public.attendance_records for update to authenticated using(public.is_organization_staff(organization_id)) with check(recorded_by=(select auth.uid()) and public.is_organization_staff(organization_id));
create policy reports_read on public.training_reports for select to authenticated using(public.is_organization_staff(organization_id) or (select public.is_admin()));
create policy reports_insert on public.training_reports for insert to authenticated with check(author_id=(select auth.uid()) and public.is_organization_staff(organization_id));
create policy reports_update on public.training_reports for update to authenticated using(author_id=(select auth.uid()) and public.is_organization_staff(organization_id)) with check(author_id=(select auth.uid()) and public.is_organization_staff(organization_id));
create policy ai_session_owner on public.ai_roleplay_sessions for select to authenticated using(user_id=(select auth.uid()));
create policy booking_participants on public.tutor_bookings for select to authenticated using(learner_id=(select auth.uid()) or tutor_id=(select auth.uid()));
create policy released_review_owner on public.examination_reviews for select to authenticated using(status='released' and exists(select 1 from public.quiz_attempts a where a.id=attempt_id and a.user_id=(select auth.uid())));
do $$declare t text;begin foreach t in array array['learning_programs','course_modules','lesson_blocks','content_translations','audio_assets','organizations','organization_members','organization_programs','training_sessions','ai_scenarios','visa_checklist_templates','visa_checklist_items','examinations','examination_reviews'] loop execute format('create policy admin_write on public.%I for all to authenticated using((select public.is_admin())) with check((select public.is_admin()))',t);end loop;end$$;

-- An edited record must be reviewed again. This applies even to direct API writes by admins.
create function private.guard_content_review() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='UPDATE' and (to_jsonb(new)-array['review_status','published','updated_at']) is distinct from (to_jsonb(old)-array['review_status','published','updated_at']) then new.review_status='draft';new.published=false;end if;
 new.updated_at=clock_timestamp();return new;end$$;
create function private.log_content_review() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_op='INSERT' or new.review_status is distinct from old.review_status or new.published is distinct from old.published then insert into private.content_review_events(entity_kind,entity_id,actor_id,review_status,published) values(tg_table_name,new.id,auth.uid(),new.review_status,new.published);end if;return new;end$$;
do $$declare t text;begin foreach t in array array['learning_programs','courses','course_modules','lessons','lesson_blocks','content_translations'] loop execute format('create trigger a_review_guard before insert or update on public.%I for each row execute function private.guard_content_review()',t);execute format('create trigger review_audit after insert or update on public.%I for each row execute function private.log_content_review()',t);end loop;
 foreach t in array array['audio_assets','organizations','training_sessions','attendance_records','training_reports','ai_scenarios','ai_roleplay_sessions','tutor_bookings','visa_checklist_templates','examinations','examination_reviews','lesson_block_progress'] loop execute format('create trigger touch_updated before update on public.%I for each row execute function private.touch_updated_at()',t);end loop;end$$;
-- Index new foreign keys and tenant/owner filters used by RLS.
create index courses_program on public.courses(program_id);
create index modules_course on public.course_modules(course_id);
create index lessons_module on public.lessons(module_id);
create index blocks_lesson on public.lesson_blocks(lesson_id);
create index blocks_deck on public.lesson_blocks(deck_id);
create index blocks_bank on public.lesson_blocks(question_bank_id);
create index blocks_audio on public.lesson_blocks(audio_asset_id);
create index translation_program on public.content_translations(program_id);
create index translation_course on public.content_translations(course_id);
create index translation_module on public.content_translations(module_id);
create index translation_lesson on public.content_translations(lesson_id);
create index translation_block on public.content_translations(block_id);
create index enrollments_program on public.program_enrollments(program_id);
create index block_progress_block on public.lesson_block_progress(block_id);
create index membership_user on public.organization_members(user_id,organization_id);
create index org_program_program on public.organization_programs(program_id);
create index sessions_program on public.training_sessions(program_id);
create index attendance_student on public.attendance_records(organization_id,student_id);
create index attendance_recorder on public.attendance_records(recorded_by);
create index reports_org on public.training_reports(organization_id);
create index reports_author on public.training_reports(author_id);
create index scenario_program on public.ai_scenarios(program_id);
create index ai_sessions_owner on public.ai_roleplay_sessions(user_id);
create index ai_sessions_scenario on public.ai_roleplay_sessions(scenario_id);
create index booking_learner on public.tutor_bookings(learner_id);
create index booking_tutor on public.tutor_bookings(tutor_id);
create index checklist_program on public.visa_checklist_templates(program_id);
create index exam_program on public.examinations(program_id);
create index exam_bank on public.examinations(bank_id);
create index attempt_examination on public.quiz_attempts(examination_id);
create index review_reviewer on public.examination_reviews(reviewer_id);
revoke all on all tables in schema private from anon,authenticated;
revoke all on all functions in schema private from public,anon,authenticated;
commit;
